#include <iostream>
  #include <iomanip>
  #include <cmath>

  int main() {
      double a = 0.0, b = 0.0, c = 0.0;
      std::cin >> a >> b >> c;

      std::cout << std::fixed << std::setprecision(2);

      if (a == 0.0) {
          if (b == 0.0) {
              if (c == 0.0) std::cout << "Vo so nghiem\n";
              else std::cout << "Vo nghiem\n";
          } else {
              double x = -c / b;
              if (x == -0.0) x = 0.0;
              std::cout << x << '\n';
          }
          return 0;
      }

      double delta = b * b - 4 * a * c;

      if (delta < 0.0) {
          std::cout << "Vo nghiem\n";
      } else if (delta == 0.0) {
          double x = -b / (2 * a);
          if (x == -0.0) x = 0.0;
          std::cout << x << '\n';
      } else {
          double canDelta = std::sqrt(delta);
          double x1 = (-b - canDelta) / (2 * a);
          double x2 = (-b + canDelta) / (2 * a);
          if (x1 > x2) {
              double tmp = x1; x1 = x2; x2 = tmp;
          }
          if (x1 == -0.0) x1 = 0.0;
          if (x2 == -0.0) x2 = 0.0;
          std::cout << x1 << " " << x2 << '\n';
      }

      return 0;
  }

